"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["94834"],{12963(e,t,n){n.d(t,{Ay:()=>o,RM:()=>s});var i=n(74848),a=n(28453);let s=[];function r(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"the-last-sentence-of-mr-wen-jiabaos-press-conference-is-worth-questioning",children:"The Last Sentence of Mr. Wen Jiabao's Press Conference Is Worth Questioning!"})}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:"2006/3/14 21:57:34"}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:'Today, Mr. Wen Jiabao, prompted by Wang Xiaoya\'s "Happy Dictionary"-style question, gave an answer regarding the RMB issue. His final sentence went like this: "The kind of administrative, one-time measures to make the RMB either appreciate or depreciate will no longer exist, and unexpected things will no longer happen." This statement is well worth discussing and questioning.'}),"\n",(0,i.jsx)(t.p,{children:'"Will no longer exist," in Chinese, implies that something once existed and persisted until recently; "will no longer happen," in Chinese, implies that something once happened. "No longer," in Chinese, corresponds to a strong commitment and slightly carries the sense of remedying certain consequences caused by what previously existed or happened. If understood in the most standard Chinese interpretation, does this imply some kind of remedy for the past "administrative, one-time measures to make the RMB either appreciate or depreciate" and the "unexpected things that happened"?'}),"\n",(0,i.jsx)(t.p,{children:'Clearly, connecting this to Mr. Wen Jiabao\'s preceding remarks: "What I want to clarify is that under the current mechanism, based on market changes, the RMB has the room and capability to float upward or downward autonomously." This merely indicates that after those "administrative, one-time measures to make the RMB either appreciate or depreciate and certain unexpected things happened," the "current mechanism" was formed. Therefore, those "administrative, one-time measures to make the RMB either appreciate or depreciate and certain unexpected things" leave no room for remedy \u2014 that is to say, what once existed and happened is all confirmed, and serves as the foundation for what continues going forward.'}),"\n",(0,i.jsx)(t.p,{children:'This foundation certainly requires strategic questioning \u2014 this has already been addressed in "Currency War and the RMB War." Beyond that, there is another significant issue: since "unexpected things" follows "will no longer happen," it can only refer to subjective matters. Otherwise, who could guarantee that objectively unexpected events "will no longer happen"? Just as no one can guarantee that tsunamis or earthquakes "will no longer happen." If the "unexpected things" that "will no longer happen" are subjective, does this mean that strategically and tactically proactive "unexpected things" "will no longer happen"? This kind of thing should never be committed to as something that "will no longer happen" \u2014 the key is who the "their" in "unexpected" refers to. In currency warfare, no one would or needs to proactively commit that strategically and tactically proactive "unexpected things" "will no longer happen."'}),"\n",(0,i.jsx)(t.p,{children:"What should happen, let it happen. Currency warfare is like actual warfare \u2014 setting aside strategy and tactics for the moment, catching the enemy off guard absolutely does not apply only within the scope defined by Sun Tzu's Art of War; it applies equally in currency warfare. Just look at the history of currency wars \u2014 battle cases are endless. \"War is deception\" \u2014 currency warfare is the same! Of course, just because it's Wang Xiaoya asking the question doesn't mean it should turn into a game show."})]})}function o(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(r,{...e})}):r(e)}},52415(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>o,contentTitle:()=>c,toc:()=>h,assets:()=>l});var i=JSON.parse('{"id":"timeline/economics/wen","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/economics/wen.md","sourceDirName":"timeline/economics","slug":"/timeline/economics/wen","permalink":"/en/timeline/economics/wen","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"wen","title":"","hide_table_of_contents":true,"sidebar_label":"Mr. Wen Jiabao\'s Last Sentence at the Press Conference Is Worth Debating! (2006/3/14 21:57:34)"},"sidebar":"timelineSidebar","previous":{"title":"Girls, Save Your First Time for Yourself! (2006/3/14 18:36:03)","permalink":"/en/timeline/essays/firstsex"},"next":{"title":"We Must Carry Out Targeted Elimination of \\"Master\\" Nan Huai-Chin\'s Pernicious Influence! (2006/3/15 18:59:29)","permalink":"/en/timeline/confucius/20060315"}}'),a=n(74848),s=n(28453),r=n(12963);let o={id:"wen",title:"",hide_table_of_contents:!0,sidebar_label:"Mr. Wen Jiabao's Last Sentence at the Press Conference Is Worth Debating! (2006/3/14 21:57:34)"},c,l={},h=[...r.RM];function d(e){return(0,a.jsx)(r.Ay,{})}function u(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>r,x:()=>o});var i=n(96540);let a={},s=i.createContext(a);function r(e){let t=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),i.createElement(s.Provider,{value:t},e.children)}}}]);